// Runtime modules that a plugin can vendor into its harness trees. `harness-kit build` copies the opted-in modules
// to <harness>/_kit/ as generated files, so an installed plugin imports only its own copy and nothing loads harness-kit.

import { readFileSync } from "node:fs"
import path from "node:path"
import type { Harness } from "./config"

export type RuntimeModule = {
  harness: Harness
  /** File name under runtime/<harness>/ and under the tree's _kit/ directory. */
  file: string
  /** Modules this one imports; they are vendored with it. */
  requires: string[]
}

export const RUNTIME_DIR = "_kit"

export const RUNTIME_MODULES = {
  frontmatter: { harness: "opencode", file: "frontmatter.ts", requires: [] },
  content: { harness: "opencode", file: "content.ts", requires: ["frontmatter"] },
  agents: { harness: "opencode", file: "agents.ts", requires: ["frontmatter"] },
  session: { harness: "opencode", file: "session.ts", requires: [] },
  render: { harness: "claude", file: "render.mjs", requires: [] },
  "template-extension": { harness: "omp", file: "template-extension.ts", requires: [] },
} as const satisfies Record<string, RuntimeModule>

export type RuntimeModuleName = keyof typeof RUNTIME_MODULES
export const RUNTIME_MODULE_NAMES = Object.keys(RUNTIME_MODULES) as RuntimeModuleName[]

const SOURCE_ROOT = path.join(import.meta.dir, "..", "runtime")

/**
 * The modules a plugin vendors, in canonical order, with their dependencies. `true` means every module of the
 * plugin's harnesses. Throws a message (without a location) on an unknown module or one for a harness the plugin lacks.
 */
export function resolveRuntime(request: boolean | string[], harnesses: readonly Harness[]): RuntimeModuleName[] {
  const wanted = new Set<RuntimeModuleName>()
  if (request === true) {
    for (const name of RUNTIME_MODULE_NAMES) if (harnesses.includes(RUNTIME_MODULES[name].harness)) wanted.add(name)
  } else if (Array.isArray(request)) {
    for (const name of request) {
      if (!(name in RUNTIME_MODULES)) throw new Error(`unknown runtime module "${String(name)}" (use ${RUNTIME_MODULE_NAMES.join(", ")})`)
      const module = RUNTIME_MODULES[name as RuntimeModuleName]
      if (!harnesses.includes(module.harness)) throw new Error(`runtime module "${name}" is for ${module.harness}, which the plugin does not list`)
      wanted.add(name as RuntimeModuleName)
    }
  }
  for (const name of wanted) for (const dep of RUNTIME_MODULES[name].requires) wanted.add(dep as RuntimeModuleName)
  return RUNTIME_MODULE_NAMES.filter((name) => wanted.has(name))
}

const COMMENT = /\.(?:[cm]?[jt]s)$/

/** The vendored text of `runtime/<harness>/<file>`: a generated-by header, then the source. */
export function vendoredFile(harness: Harness, file: string, generatedBy: string): string {
  if (!COMMENT.test(file)) throw new Error(`cannot add a header to ${file}`)
  const source = readFileSync(path.join(SOURCE_ROOT, harness, file), "utf8")
  return `// Generated by ${generatedBy}. Do not edit.\n${source}`
}

/** The vendored text of a module, with the harness and file it belongs to. */
export function vendoredSource(name: RuntimeModuleName, generatedBy: string): { harness: Harness; file: string; contents: string } {
  const { harness, file } = RUNTIME_MODULES[name]
  return { harness, file, contents: vendoredFile(harness, file, generatedBy) }
}
